import{c as t,Q as a,j as l,m as r}from"./chunks/framework.DjobWxAB.js";const f=JSON.parse('{"title":"전기 안전","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/Safety/electrical-safety.md","filePath":"ko/manual/Safety/electrical-safety.md","lastUpdated":1779182288000}'),i={name:"ko/manual/Safety/electrical-safety.md"};function s(o,e,n,d,c,p){return a(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="전기-안전" tabindex="-1">전기 안전 <a class="header-anchor" href="#전기-안전" aria-label="Permalink to &quot;전기 안전&quot;">​</a></h1><p>RBQ와 충전기·도킹 스테이션 등 <strong>전기 장비를 다룰 때</strong> 지켜야 할 안전 사항입니다.</p><ul><li><strong>적용 시점</strong>: 로봇 충전·점검·수리 시, 전기 장비를 직접 다룰 때</li><li><strong>현장 운용</strong>: 위험 환경·군용·순찰 등에서는 이상적인 전기 환경을 유지하기 어려울 수 있으므로, 충전·내부 점검·배선 작업은 가능한 한 건조하고 안전한 장소에서 수행하세요.</li></ul><p><strong>고전압 구간·젖은 부위·손상된 케이블·커넥터</strong>는 감전 위험이 큽니다. 외관상 멀쩡해도 <strong>고전압·강한 전자기 환경</strong>에 노출되면 내부 손상으로 잠재적 고장이 발생할 수 있으므로, 이상 징후 시 사용을 중단하고 점검하세요.</p><h2 id="일반-주의사항" tabindex="-1">일반 주의사항 <a class="header-anchor" href="#일반-주의사항" aria-label="Permalink to &quot;일반 주의사항&quot;">​</a></h2><div class="custom-block safety-label-block" style="padding:1rem 1.5rem;border-radius:8px;background:rgba(192, 57, 43, 0.12);border-left:4px solid #c0392b;display:flex;gap:1rem;align-items:stretch;"><div style="display:flex;align-items:center;justify-content:center;flex-shrink:0;width:2.5rem;"><span style="font-size:2.5rem;line-height:1;color:#c0392b;" aria-hidden="true">⚠</span></div><div style="flex:1;"><p class="custom-block-title">위험</p><p>감전 위험이 있는 전기 장치 부근에는 반드시 경고 표시를 하세요.</p></div></div><div class="custom-block safety-label-block" style="padding:1rem 1.5rem;border-radius:8px;background:rgba(211, 84, 0, 0.12);border-left:4px solid #d35400;display:flex;gap:1rem;align-items:stretch;"><div style="display:flex;align-items:center;justify-content:center;flex-shrink:0;width:2.5rem;"><span style="font-size:2.5rem;line-height:1;color:#d35400;" aria-hidden="true">⚠</span></div><div style="flex:1;"><p class="custom-block-title">주의</p><p>1) 덮개를 찢거나 손상시키거나 제거하지 마세요. 라벨이 부착된 부품·장치 및 주변 부품을 다룰 때 주의하세요.<br>2) 감전을 피하기 위해 내부 전기 부품에 직접 접촉하지 마세요.<br>3) 충전·점검·수리 시에는 젖은 손으로 전원 케이블, 충전 포트, 제어기를 만지지 마세요.</p></div></div><h2 id="충전-및-전원" tabindex="-1">충전 및 전원 <a class="header-anchor" href="#충전-및-전원" aria-label="Permalink to &quot;충전 및 전원&quot;">​</a></h2><ul><li><strong>지정 충전기만 사용</strong>: RBQ10은 제공된 RBQ10 전용 충전기 또는 RBQ10 도킹 스테이션으로만 충전하세요. 다른 충전기는 손상·화재·감전 위험이 있습니다.</li><li><strong>케이블 점검</strong>: 충전 케이블·전원 케이블이 꼬이거나 손상되지 않았는지 확인하고, 손상 시 사용하지 마세요.</li><li><strong>접지</strong>: 충전·점검을 수행하는 장소에서는 제어기·도킹 스테이션 등이 규정에 맞게 접지되어 있도록 하세요. 현장·이동 환경에서는 가능한 한 안전한 장소에서 충전하세요.</li></ul><h2 id="수리-및-분해" tabindex="-1">수리 및 분해 <a class="header-anchor" href="#수리-및-분해" aria-label="Permalink to &quot;수리 및 분해&quot;">​</a></h2><div class="custom-block safety-label-block" style="padding:1rem 1.5rem;border-radius:8px;background:rgba(211, 84, 0, 0.12);border-left:4px solid #d35400;display:flex;gap:1rem;align-items:stretch;"><div style="display:flex;align-items:center;justify-content:center;flex-shrink:0;width:2.5rem;"><span style="font-size:2.5rem;line-height:1;color:#d35400;" aria-hidden="true">⚠</span></div><div style="flex:1;"><p class="custom-block-title">주의</p><p>내부 점검·부품 교환·케이블 작업 시 <strong>반드시 전원을 끄고</strong>, 필요 시 배터리 연결을 해제하세요.</p></div></div><ul><li><strong>무단 개조 금지</strong>: 전기 회로·배선을 사용자가 임의로 변경하지 마세요.</li></ul><p>문제 발생 시 Rainbow Robotics에 문의하세요. <a href="/RBQ/ko/manual/Troubleshooting/error-reporting.html">문의하기</a> 페이지를 참고하세요.</p>',13)])])}const g=t(i,[["render",s]]);export{f as __pageData,g as default};
